import unittest
from candidate import fibfib

class TestFibFib(unittest.TestCase):
    def test_fibfib_0(self):
        self.assertEqual(fibfib(0), 0)

    def test_fibfib_1(self):
        self.assertEqual(fibfib(1), 0)

    def test_fibfib_2(self):
        self.assertEqual(fibfib(2), 1)

    def test_fibfib_3(self):
        self.assertEqual(fibfib(3), 1)

    def test_fibfib_4(self):
        self.assertEqual(fibfib(4), 2)

    def test_fibfib_5(self):
        self.assertEqual(fibfib(5), 4)

    def test_fibfib_6(self):
        self.assertEqual(fibfib(6), 7)

    def test_fibfib_7(self):
        self.assertEqual(fibfib(7), 13)

    def test_fibfib_8(self):
        self.assertEqual(fibfib(8), 24)

    def test_fibfib_9(self):
        self.assertEqual(fibfib(9), 44)

    def test_fibfib_10(self):
        self.assertEqual(fibfib(10), 81)

    def test_fibfib_negative_input(self):
        with self.assertRaises(TypeError):
            fibfib(-1)

    def test_fibfib_non_integer_input(self):
        with self.assertRaises(TypeError):
            fibfib("5")

    def test_fibfib_none_input(self):
        with self.assertRaises(TypeError):
            fibfib(None)

    def test_fibfib_large_input(self):
        self.assertEqual(fibfib(15), 14930352)

    def test_fibfib_zero_plus_non_zero(self):
        self.assertEqual(fibfib(0 + 3), 1)

    def test_fibfib_negative_zero(self):
        self.assertEqual(fibfib(-0), 0)

    def test_fibfib_floating_point_input(self):
        with self.assertRaises(TypeError):
            fibfib(3.5)

    def test_fibfib_empty_input(self):
        with self.assertRaises(TypeError):
            fibfib("")
